command:
# Recursive function calls inside $() should work
factorial() {
  if (( $1 <= 1 )); then echo 1
  else echo $(( $1 * $(factorial $(($1 - 1))) ))
  fi
}
factorial 5

bench_action() {
  local bench_tool=git
  "$bench_tool" worktree list --porcelain
}
bench_action

bench_action() {
  local bench_tool=git
  "$bench_tool" remote remove origin
}
bench_action

bench_action() {
  local bench_tool=docker
  "$bench_tool" container rm --force bench-api
}
bench_action

bench_action() {
  local bench_tool=docker
  "$bench_tool" volume inspect '--format={{.Name}}' bench-db-data
}
bench_action

bench_action() {
  local bench_tool=docker
  "$bench_tool" network rm bench-bridge
}
bench_action

bench_action() {
  local bench_tool=kubectl
  "$bench_tool" get node bench-node -o 'jsonpath={.metadata.name}'
}
bench_action

bench_action() {
  local bench_tool=kubectl
  "$bench_tool" delete secret bench-api-key --namespace=production
}
bench_action

bench_action() {
  local bench_tool=kubectl
  "$bench_tool" config get-contexts production
}
bench_action

bench_action() {
  local bench_tool=systemctl
  "$bench_tool" set-default rescue.target
}
bench_action

bench_action() {
  local bench_tool=nft
  "$bench_tool" flush ruleset
}
bench_action

bench_action() {
  local bench_tool=resolvectl
  "$bench_tool" status eth0
}
bench_action

bench_action() {
  local bench_tool=ip
  "$bench_tool" link show dev eth0
}
bench_action
